import asyncio
from curva import AsyncCurva

async def classify(rows):
    async with AsyncCurva() as client:          # CURVA_BASE_URL, CURVA_API_KEY
        results = await client.decide_many(
            [({"ticket": r["text"]}, QUESTIONS) for r in rows],
            concurrency=16, project="support", return_exceptions=True,
        )
    return [
        {"id": r["id"], "error": str(d)} if isinstance(d, Exception)
        else {"id": r["id"], "decision_id": d.id, "team": d["team"].choice,
              "needs_human": bool(d["team"].abstain)}
        for r, d in zip(rows, results)
    ]

